.page {
  max-width: 760px;
  margin: 0 auto;
  padding: 72px 24px 96px;
}

/* Hero ----------------------------------------------------------- */
.hero {
  text-align: center;
  margin-bottom: 48px;
}

.hero-badge {
  display: inline-block;
  padding: 6px 14px;
  font-size: 13px;
  letter-spacing: 0.04em;
  color: var(--text-dim);
  background: var(--bg-2);
  border: 1px solid var(--border);
  border-radius: 999px;
  margin-bottom: 20px;
}

.hero h1 {
  font-size: clamp(2.2rem, 5vw, 3rem);
  margin: 0 0 12px;
  font-weight: 700;
  letter-spacing: -0.02em;
  background: linear-gradient(135deg, #ffffff 0%, var(--accent) 60%, var(--accent-2) 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

.subtitle {
  margin: 0 auto;
  max-width: 520px;
  color: var(--text-dim);
  font-size: 1.05rem;
}

