.question {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 18px 20px;
  background: transparent;
  border: 0;
  color: var(--text);
  font: inherit;
  font-size: 1.02rem;
  font-weight: 500;
  text-align: left;
  cursor: pointer;
  transition: background 0.2s ease;
}

.question:hover { background: rgba(255, 255, 255, 0.025); }

.question:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: -2px;
}

.q-text { flex: 1; }

.chevron {
  width: 22px;
  height: 22px;
  flex-shrink: 0;
  position: relative;
  border-radius: 50%;
  background: var(--bg-3);
  border: 1px solid var(--border-strong);
  transition: transform 0.25s ease, background 0.25s ease, border-color 0.25s ease;
}

.chevron::before,
.chevron::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  width: 9px;
  height: 1.5px;
  background: var(--text);
  border-radius: 2px;
  transform-origin: center;
  transition: transform 0.25s ease, opacity 0.25s ease;
