.chevron::before { transform: translate(-50%, -50%); }
.chevron::after  { transform: translate(-50%, -50%) rotate(90deg); }

.example.open .chevron {
  background: var(--accent);
  border-color: var(--accent);
  transform: rotate(180deg);
}
.example.open .chevron::before { background: #0b0d12; }
.example.open .chevron::after  { opacity: 0; }

/* Details panel -------------------------------------------------- */
.details {
  padding: 0 20px;
  max-height: 0;
  overflow: hidden;
  opacity: 0;
  transition:
    max-height 0.35s ease,
    padding 0.3s ease,
    opacity 0.25s ease;
  border-top: 1px solid transparent;
  color: var(--text-dim);
}

.details[hidden] { display: block; } /* override default to allow animation; JS toggles class */

.example.open .details {
  padding: 14px 20px 20px;
  max-height: 600px;
  opacity: 1;
  border-top-color: var(--border);
}

.details p { margin: 0; }
.details strong { color: var(--text); font-weight: 600; }
.details em { color: var(--accent-2); font-style: normal; }

/* Footer --------------------------------------------------------- */
.foot {
  margin-top: 56px;
  text-align: center;
  color: var(--text-mute);
  font-size: 0.9rem;
}

/* Mobile --------------------------------------------------------- */
@media (max-width: 480px) {
  .page { padding: 48px 16px 64px; }
  .question { padding: 16px; font-size: 0.98rem; }
  .example.open .details { padding: 12px 16px 18px; }
}
